			name := filepath.Base(srcPath)
			dstPath := filepath.Join(s.snapTmpDirPath, name)
			if err := os.Rename(srcPath, dstPath); err != nil {
				return err
			}
			if !db.IsValidSQLiteWALFile(dstPath) {
				return fmt.Errorf("%s is not a valid SQLite WAL file", name)
			}
