				if err != nil {
					return n, err
				}
				if fullNeeded {
					return n, fmt.Errorf("full snapshot needed before noop can be applied")
				}
			}
			// No data follows this header type. Any leftover bytes are an error.
			if s.buf.Len() > 0 {
				return n, fmt.Errorf("unexpected data after noop header")
			}
			s.isNoop = true
			return n, nil
