	if s.sinkW == nil {
		// IncrementalFile or Noop path — no data expected after header.
		if s.isNoop {
			return 0, fmt.Errorf("unexpected data after noop header")
		}
		return 0, fmt.Errorf("unexpected data after incremental file header")
	}
	return s.sinkW.Write(p)
}

