// mustWriteTempFile writes the given content to a temporary file and returns
// its path. It fails the test if the file cannot be written.
func mustWriteTempFile(t *testing.T, b []byte) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "temp-file")
	if err := os.WriteFile(path, b, 0644); err != nil {
		t.Fatalf("failed to write temp file: %v", err)
	}
	return path
}

func Test_CRC32(t *testing.T) {
	content := []byte("hello, world")
	path := mustWriteTempFile(t, content)

	got, err := CRC32(path)
	if err != nil {
		t.Fatalf("CRC32 failed: %v", err)
	}
	want := crc32.Checksum(content, crc32.MakeTable(crc32.Castagnoli))
	if got != want {
		t.Errorf("CRC32 = %08x, want %08x", got, want)
	}
}

func Test_CRC32FileNotFound(t *testing.T) {
	if _, err := CRC32("nonexistent-file"); err == nil {
		t.Error("expected error for non-existent file, got none")
	}
}

func Test_CRC32Writer(t *testing.T) {
	content := []byte("some data to checksum")

	var sink []byte
	buf := &bytesBuffer{b: &sink}
	w := NewCRC32Writer(buf)
	if _, err := w.Write(content); err != nil {
		t.Fatalf("CRC32Writer.Write failed: %v", err)
	}

	if got, want := w.Sum32(), crc32.Checksum(content, crc32.MakeTable(crc32.Castagnoli)); got != want {
		t.Errorf("CRC32Writer.Sum32 = %08x, want %08x", got, want)
	}
	if string(sink) != string(content) {
		t.Errorf("CRC32Writer did not pass through data: got %q, want %q", string(sink), string(content))
	}
}

// bytesBuffer is a minimal io.Writer that appends to a backing slice.
type bytesBuffer struct {
	b *[]byte
}

func (w *bytesBuffer) Write(p []byte) (int, error) {
	*w.b = append(*w.b, p...)
	return len(p), nil
}

func Test_WriteCRC32SumFileRoundTrip(t *testing.T) {
	path := filepath.Join(t.TempDir(), "checksum")
	var sum uint32 = 0x1a2b3c4d

	if err := WriteCRC32SumFile(path, sum, NoSync); err != nil {
		t.Fatalf("WriteCRC32SumFile failed: %v", err)
	}

	// File should contain the hex string.
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading checksum file: %v", err)
	}
	if got, want := string(b), "1a2b3c4d"; got != want {
		t.Errorf("file contents = %q, want %q", got, want)
	}

