	got, err := ReadCRC32SumFile(path)
	if err != nil {
		t.Fatalf("ReadCRC32SumFile failed: %v", err)
	}
	if got != sum {
		t.Errorf("ReadCRC32SumFile = %08x, want %08x", got, sum)
	}
}

