func Test_CompareCRC32SumFile(t *testing.T) {
	content := []byte("data-integrity-check")
	dataPath := mustWriteTempFile(t, content)

	sum, err := CRC32(dataPath)
	if err != nil {
		t.Fatalf("CRC32 failed: %v", err)
	}

	crcPath := dataPath + ".crc32"
	if err := WriteCRC32SumFile(crcPath, sum, NoSync); err != nil {
